mapper.select:
select u.user_id as userId, u.user_name as userName, u.nick_name as nickName, u.dept_id as deptId, u.phonenumber as phonenumber, r.read_time as readTime from sys_notice_read r inner join sys_user u on u.user_id = r.user_id and u.del_flag = '0' where r.notice_id = #{noticeId}
and u.nick_name like concat('%', #{nickNameLike}, '%')
order by r.read_time desc
